"""Explicit paths for all data generated by one pipeline run."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class WorkspacePaths:
    root: Path
    raw_images: Path
    sharp_images: Path
    masks: Path
    sparse: Path
    dense: Path
    database: Path
    project_ini: Path
    glomap_ini: Path
    log_file: Path

    @classmethod
    def create(cls, root: Path) -> WorkspacePaths:
        root = root.expanduser().resolve()
        paths = cls(
            root=root,
            raw_images=root / "raw_images",
            sharp_images=root / "sharp_images",
            masks=root / "masks",
            sparse=root / "sparse",
            dense=root / "dense",
            database=root / "database.db",
            project_ini=root / "project.ini",
            glomap_ini=root / "glomap_config.ini",
            log_file=root / "pipeline_times.log",
        )
        for directory in (paths.root, paths.raw_images, paths.sharp_images, paths.masks):
            directory.mkdir(parents=True, exist_ok=True)
        return paths